import { describe, expect, test } from 'bun:test';
import { cleanPromptText } from './prompt-text';

const MAX = 2_000;

describe('cleanPromptText', () => {
  test('keeps a plain prompt', () => {
    expect(cleanPromptText('  fix the login bug  ', MAX)).toBe('fix the login bug');
  });

  test.each([
    '<task-notification> <task-id>abc</task-id> done </task-notification>',
    'Base directory for this skill: /Users/me/.claude/skills/x',
    'Caveat: The messages below were generated by the user while running local commands.',
    '<system-reminder>Only a reminder</system-reminder>',
    '<local-command-stdout>ok</local-command-stdout>',
    '   ',
  ])('drops harness-only text: %s', (raw) => {
    expect(cleanPromptText(raw, MAX)).toBeNull();
  });

  test('strips reminders around a real prompt', () => {
    expect(cleanPromptText('<system-reminder>ctx</system-reminder>\nship it', MAX)).toBe('ship it');
  });

  test('unwraps pasted content', () => {
    expect(cleanPromptText('<pasted_content id="9099">We are building X</pasted_content> please review', MAX)).toBe(
      'We are building X please review',
    );
  });

  test('unwraps pasted content logged without its closing tag', () => {
    expect(cleanPromptText('\n\n<pasted_content id="545d">\nPick the next 3 items', MAX)).toBe('Pick the next 3 items');
  });

  test('renders slash commands with their arguments', () => {
    expect(
      cleanPromptText('<command-message>review</command-message><command-name>/review</command-name><command-args>42</command-args>', MAX),
    ).toBe('/review 42');
    expect(cleanPromptText('<command-name>/clear</command-name>', MAX)).toBe('/clear');
  });

  test('renders shell escapes', () => {
    expect(cleanPromptText('<bash-input>git status</bash-input>', MAX)).toBe('! git status');
  });

  test('truncates to the limit', () => {
    expect(cleanPromptText('a'.repeat(10), 4)).toBe('aaaa');
  });
});
